#!/usr/bin/env python3
"""Assemble explicit Worker modules, without installing dependencies or a bundler."""
import hashlib
import html
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
catalog = (ROOT / 'categories.json').read_text()
data = json.loads(catalog)
assert data['status'] == 'published' and data['version'] == '1'
assert [c['id'] for c in data['categories']] == list(range(1, 100))
digest = hashlib.sha256(catalog.encode()).hexdigest()
(ROOT / 'src/catalog.mjs').write_text(
    '// Generated by scripts/package.py. Do not edit.\n'
    + 'export const catalogJSON = ' + json.dumps(catalog) + ';\n'
    + 'export const catalog = JSON.parse(catalogJSON);\n'
    + 'export const catalogHash = ' + json.dumps(digest) + ';\n'
)
assets = {}
for name, kind in [('site.css', 'text/css'), ('app.mjs', 'text/javascript'), ('codec.mjs', 'text/javascript'), ('explore.mjs', 'text/javascript')]:
    assets['/assets/' + name] = {'body': (ROOT / 'public' / name).read_text(), 'type': kind + '; charset=utf-8'}
(ROOT / 'src/assets.mjs').write_text('// Generated by scripts/package.py. Do not edit.\nexport const assets = ' + json.dumps(assets) + ';\n')

# This deliberately small Markdown subset keeps the public post easy to edit in a
# PR while escaping all source text before it becomes Worker HTML.
post = (ROOT / 'blog/why-ai-used.md').read_text().strip().split('\n\n')
assert post[0].startswith('# ') and post[0].count('\n') == 0
def inline(source):
    chunks = re.split(r'(\[[^]]+\]\(https://[^)]+\)|`[^`]+`)', source)
    out = []
    for chunk in chunks:
        link = re.fullmatch(r'\[([^]]+)\]\((https://[^)]+)\)', chunk)
        if link:
            out.append(f'<a href="{html.escape(link[2], quote=True)}">{html.escape(link[1])}</a>')
        elif chunk.startswith('`') and chunk.endswith('`'):
            out.append('<code>' + html.escape(chunk[1:-1]) + '</code>')
        else:
            out.append(html.escape(chunk))
    return ''.join(out)
title = post[0][2:]
body = ''.join('<p>' + inline(' '.join(block.splitlines())) + '</p>' for block in post[1:])
(ROOT / 'src/blog.mjs').write_text(
    '// Generated by scripts/package.py from blog/why-ai-used.md. Do not edit.\n'
    + 'export const postTitle = ' + json.dumps(title) + ';\n'
    + 'export const postBody = ' + json.dumps(body) + ';\n'
)
modules = ['src/worker.mjs', 'src/render.mjs', 'src/explore.mjs', 'src/analytics.mjs', 'src/catalog.mjs', 'src/assets.mjs', 'src/blog.mjs', 'src/qr.mjs', 'public/codec.mjs', 'vendor/qrcode.mjs']
payload = {
    'metadata': {
        'main_module': 'worker.mjs',
        'compatibility_date': '2026-10-23',
        'observability': {'enabled': True, 'head_sampling_rate': 0.01, 'redact_query_string': True,
                          'logs': {'enabled': True, 'invocation_logs': False, 'head_sampling_rate': 0.01},
                          'traces': {'enabled': True, 'head_sampling_rate': 0.01}},
        'bindings': [{'type': 'analytics_engine', 'name': 'ANALYTICS', 'dataset': 'aiused_requests'}],
    },
    'modules': {name: (ROOT / name).read_text() for name in modules},
}
# Wrangler uploads the entrypoint by basename. A root shim keeps every relative
# import inside the module namespace instead of resolving ../ above its root.
payload['modules']['worker.mjs'] = "export { default } from './src/worker.mjs';\n"
artifacts = ROOT / 'artifacts'
artifacts.mkdir(exist_ok=True)
for name, content in payload['modules'].items():
    target = artifacts / 'worker-modules' / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)
(artifacts / 'upload.json').write_text(json.dumps(payload))
print(json.dumps({'modules': len(payload['modules']), 'source_bytes': sum(len(s.encode()) for s in payload['modules'].values()), 'vocabulary_sha256': digest}))
